import type { BankQuestion } from "@/lib/bank";

/** Reading Comprehension (English Language): 90 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id": "eng-reading-comprehension-1", "question": "Passage: Community libraries in small towns have quietly changed their role over the past decade. Once places where people simply borrowed books, many now run coding clubs for teenagers, help elderly residents fill in online forms and host weekly storytelling sessions for toddlers. Librarians say footfall has risen even as book loans have fallen, because people come for services they cannot easily find elsewhere. Some councils, however, still judge libraries only by the number of books issued, and cut their budgets when loan figures drop. Such decisions, critics argue, measure the wrong thing and punish libraries for adapting to what their communities actually need. Question: The passage is mainly about:", "options": ["why teenagers have stopped reading books", "how councils raise money to run public libraries", "how small-town libraries have widened their role while still being judged by an outdated measure", "the history of storytelling sessions for young children"], "answer": 2, "explanation": "The passage describes the new services libraries offer and criticises councils that still judge them only by book loans. Teenagers and storytelling are details, not the main idea.", "difficulty": "easy", "source": "IBPS PO · SBI PO · CDS pattern"},
  {"id": "eng-reading-comprehension-2", "question": "Passage: The new metro line was expected to ease traffic on the city's main avenue. In its first month, though, ridership was meagre: trains that could carry a thousand passengers ran with barely a hundred aboard. Officials blamed the lack of feeder buses, since most stations stood a long walk from residential areas. Once the transport department added shuttle services from nearby colonies, numbers began to climb, and by the sixth month the line was carrying close to its planned load during peak hours. The episode taught planners that a railway is only as useful as the ways people have of reaching it. Question: As used in the passage, the word 'meagre' most nearly means:", "options": ["steady", "excessive", "scanty", "irregular"], "answer": 2, "explanation": "Trains built for a thousand passengers carried barely a hundred, so 'meagre' means scanty or inadequate. 'Excessive' is its opposite.", "difficulty": "easy", "source": "IBPS PO · SBI PO · CDS pattern"},
  {"id": "eng-reading-comprehension-3", "question": "Passage: Mangrove forests grow where rivers meet the sea, in a zone that floods with salt water twice a day. Few trees can survive such conditions, but mangroves have evolved special adaptations. Some species push up breathing roots, called pneumatophores, through the mud so that they can take in air when the soil is waterlogged. Others filter out most of the salt at their roots or shed it through their leaves. Their tangled root systems slow down waves, trap sediment and shelter young fish. Villages behind dense mangrove belts have often suffered less damage from storm surges than those on bare coasts. Question: According to the passage, pneumatophores help mangroves to:", "options": ["trap sediment brought by rivers", "take in air when the soil is waterlogged", "shelter young fish from predators", "shed excess salt through their leaves"], "answer": 1, "explanation": "The passage says breathing roots called pneumatophores let mangroves take in air from waterlogged mud. Shedding salt is done by other species, and trapping sediment is a job of the tangled root system as a whole.", "difficulty": "easy", "source": "IBPS PO · SBI PO · CDS pattern"},
  {"id": "eng-reading-comprehension-4", "question": "Passage: It is fashionable to sneer at handwritten letters as a relic of slower times. Yet anyone who has found an old letter from a grandparent tucked inside a book knows the small jolt of recognising a familiar slant of the pen, the crossed-out word, the hurried postscript. An email can carry the same words, but it cannot carry the hand that wrote them. We need not abandon our keyboards; we might simply keep a few sheets of paper for the occasions that deserve them: a thank-you, a condolence, a birthday wish to someone far away. Question: The author's attitude towards handwritten letters is best described as:", "options": ["appreciative and gently persuasive", "neutral and purely factual", "nostalgic to the point of rejecting technology", "hostile and dismissive"], "answer": 0, "explanation": "The author values handwritten letters and mildly urges readers to write some. The author does not reject technology ('We need not abandon our keyboards'), so the last option overstates it.", "difficulty": "easy", "source": "IBPS PO · SBI PO · CDS pattern"},
  {"id": "eng-reading-comprehension-5", "question": "Passage: When a village in a drought-prone district faced repeated crop failures, its residents did not wait for a large dam. They built hundreds of small check dams and contour trenches, banned the cutting of trees on common land and agreed to grow crops that needed less water. Within a decade the water table had risen, wells that had been dry for years held water again, and families who had migrated to cities began to return. Visitors now come from across the country to study the village, though its leaders insist that the real secret was not engineering but agreement among neighbours. Question: It can be inferred that the village leaders believe its success depended most on:", "options": ["generous funding from the government", "the construction of a large dam", "collective decision-making by the residents", "advanced engineering techniques"], "answer": 2, "explanation": "The leaders say the secret was 'not engineering but agreement among neighbours', which points to collective decisions. The passage says the village did not wait for a large dam and never mentions government funding.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · CDS pattern"},
  {"id": "eng-reading-comprehension-6", "question": "Passage: Many people assume that the colour of an egg's shell tells us something about its nutrition. Brown eggs often cost more in shops, and buyers tend to think they are healthier or more natural. In fact, shell colour depends almost entirely on the breed of the hen: hens with white feathers and white ear-lobes usually lay white eggs, while many breeds with red or brown feathers lay brown ones. What the hen eats and how it is raised affect the yolk far more than its breed does. A brown egg and a white egg from hens on the same diet are, for practical purposes, nutritionally the same. Question: The primary purpose of the passage is to:", "options": ["explain how hens are raised on farms", "compare the prices of eggs in different shops", "correct a common misconception about eggs", "advise buyers to prefer white eggs"], "answer": 2, "explanation": "The passage sets up a popular belief (brown eggs are healthier) and shows it is mistaken. It recommends neither colour, so 'advise buyers to prefer white eggs' is wrong.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · CDS pattern"},
  {"id": "eng-reading-comprehension-7", "question": "Passage: Honeybees tell one another where food is through a movement known as the waggle dance. A forager returning to the hive runs in a straight line while shaking its abdomen, then loops back and repeats the run. The angle of the straight run relative to the vertical comb shows the direction of the food relative to the sun, and the length of the waggle run shows distance: the longer the run, the farther the flowers. Because the sun moves across the sky, bees adjust the angle of their dance through the day, so a dance performed at noon for the same flowers differs from one performed in the morning. Question: Which of the following is NOT supported by the passage?", "options": ["Bees signal the quality of the nectar by the speed of their loops", "Bees use the position of the sun as a reference for direction", "A dance for the same flowers changes its angle during the day", "The length of the waggle run tells other bees how far away the food is"], "answer": 0, "explanation": "The passage links the angle to direction and the length of the run to distance, and says the angle shifts as the sun moves. It says nothing about nectar quality or the speed of the loops.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · CDS pattern"},
  {"id": "eng-reading-comprehension-8", "question": "Passage: The committee's report was candid about the failures of the flood-warning system. It admitted that sirens in three districts had not sounded, that text alerts had reached residents hours late, and that officials had ignored early readings from upstream gauges. Rather than blaming individuals, the report traced these lapses to a culture in which nobody owned the system from end to end. Its recommendations were modest in cost but sweeping in scope: a single agency to run warnings, regular drills, and publication of every gauge reading in real time, so that citizens could see for themselves when a river was rising. Question: In the passage, 'sweeping' most nearly means:", "options": ["wide-ranging", "cleaning", "victorious", "hasty"], "answer": 0, "explanation": "'Modest in cost but sweeping in scope' contrasts low cost with broad reach, so 'sweeping' means wide-ranging. 'Cleaning' is the literal sense and does not fit.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · CDS pattern"},
  {"id": "eng-reading-comprehension-9", "question": "Passage: For centuries sailors navigated by the stars, but finding longitude at sea remained dangerously difficult. Latitude could be judged from the height of the sun at noon; longitude required knowing the exact time at the home port while at sea, and the pendulum clocks of the day could not keep time on a rolling ship. In the eighteenth century a self-taught English carpenter, John Harrison, spent decades building a series of marine timekeepers. His fourth, built like a large pocket watch, lost only a few seconds on a voyage to the Caribbean. Accurate chronometers soon made long voyages far safer. Question: Which is the most suitable title for the passage?", "options": ["The Invention of the Pendulum Clock", "How Sailors Read the Stars", "Solving the Longitude Problem", "A Voyage to the Caribbean"], "answer": 2, "explanation": "The whole passage is about the difficulty of finding longitude and how Harrison's timekeepers solved it. Star navigation, pendulum clocks and the voyage are only details.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · CDS pattern"},
  {"id": "eng-reading-comprehension-10", "question": "Passage: A city once tried to reduce its population of cobras by paying a reward for every dead snake. At first the scheme seemed to work: thousands of skins were handed in. Then officials noticed that the number of rewards kept rising while sightings in the streets did not fall. Enterprising residents had begun breeding cobras at home to collect the money. When the scheme was scrapped, the breeders released their now worthless snakes, and the city ended up with more cobras than before. Economists still use the story to warn that a badly designed incentive can produce the very problem it was meant to solve. Question: Economists use the story to illustrate that:", "options": ["breeding animals at home is always profitable", "governments should never offer cash rewards", "snakes are especially hard to control in cities", "an incentive can backfire when people find ways to exploit it"], "answer": 3, "explanation": "The passage ends by warning that a badly designed incentive can produce the problem it was meant to solve. It does not say rewards should never be offered; 'never' goes beyond the text.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · CDS pattern"},
  {"id": "eng-reading-comprehension-11", "question": "Passage: The minister announced, with considerable fanfare, that the new highway would be completed 'well ahead of schedule'. This was the fourth such announcement in six years. The first had promised completion by 2019; the second, by 2021; the third, after a 'thorough review', by 2023. Each time the ribbon was ready, the scissors sharpened and the press invited. Commuters who have spent those years inching past half-built flyovers may be forgiven for not reaching for their party hats just yet. Question: The tone of the passage is:", "options": ["celebratory", "apologetic", "indifferent", "sarcastic"], "answer": 3, "explanation": "By listing the broken deadlines and mocking the ready ribbon and 'party hats', the writer ridicules the announcement, so the tone is sarcastic. Nothing in it is truly celebratory.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · CDS pattern"},
  {"id": "eng-reading-comprehension-12", "question": "Passage: Sleep researchers have found that teenagers' internal body clocks shift later during puberty: most adolescents do not feel sleepy until around eleven at night and naturally wake after eight. Schools that begin classes at seven-thirty therefore make students wake in the middle of their biological night. Several districts that moved their start time to nine reported that students slept longer, attended more regularly and did slightly better in morning tests. Opponents point to the cost of rescheduling buses and the disruption to parents' working hours, but supporters argue that these are problems of convenience, while lost sleep is a problem of health. Question: According to the passage, early school start times harm teenagers because:", "options": ["school buses often arrive late in the morning", "morning tests are harder than afternoon tests", "they force students to wake before their body clocks are ready", "teenagers waste their evenings on screens"], "answer": 2, "explanation": "The passage says puberty shifts the body clock later, so a 7:30 start makes students wake in their biological night. Screens and late buses are never mentioned.", "difficulty": "moderate", "source": "IBPS PO · SBI PO · CDS pattern"},
  {"id": "eng-reading-comprehension-13", "question": "Passage: Ancient Roman concrete has outlasted many modern structures, and for years engineers puzzled over why. Recent analysis of samples from a Roman tomb suggests part of the answer: the builders mixed in quicklime, which left small white lumps of lime scattered through the material. When cracks later formed and water seeped in, it dissolved some of this lime, which then recrystallised as calcium carbonate and sealed the crack. Modern concrete, made to a smooth and uniform mix, lacks these reservoirs. Researchers are now testing whether adding lime lumps on purpose could give today's concrete a similar ability to heal itself. Question: Which of the following can be inferred from the passage?", "options": ["Modern concrete cracks more often than Roman concrete did", "Water always weakens concrete structures", "Roman builders understood the chemistry of self-healing concrete", "The uniformity valued in modern concrete may remove a feature that helps old concrete repair itself"], "answer": 3, "explanation": "The lime lumps that heal cracks are missing from smooth, uniform modern mixes, so uniformity removes the self-healing reservoirs. The passage never says the Romans understood the chemistry or that modern concrete cracks more often, and here water actually helps the repair.", "difficulty": "hard", "source": "IBPS PO · SBI PO · CDS pattern"},
  {"id": "eng-reading-comprehension-14", "question": "Passage: Translation is often described as the faithful transfer of meaning from one language to another, as if meaning were a parcel that could be lifted out of one box and placed unchanged into another. Anyone who has tried to translate a joke knows better. Puns depend on sounds that the second language does not share; idioms carry histories that cannot be explained without killing them. A good translator therefore makes choices, sacrificing a pun here to keep a rhythm there, and every such choice is an act of interpretation. To read a translation is to read two authors at once. Question: The author would most likely agree that:", "options": ["a perfect translation keeps every element of the original", "jokes should never be translated", "translators should explain every idiom in a footnote", "every translation reflects the translator's own judgement"], "answer": 3, "explanation": "The author calls every choice 'an act of interpretation' and says a translation has 'two authors', so each translation carries the translator's judgement. The author says idioms die when explained, so footnoting every idiom goes against the passage.", "difficulty": "hard", "source": "IBPS PO · SBI PO · CDS pattern"},
  {"id": "eng-reading-comprehension-15", "question": "Passage: Supporters of plastic bag bans often cite the image of a turtle tangled in a carrier bag. The image is real, but the economics are more complicated. A cotton tote must be reused many dozens of times before its overall environmental cost, counting the water and energy used to grow and process the cotton, falls below that of a thin plastic bag used once. Many shoppers, it turns out, collect totes faster than they wear them out. None of this means the bans are wrong; it means that their benefit depends less on the bag we carry than on how long we keep carrying it. Question: The final sentence of the passage serves to:", "options": ["qualify the criticism that came before and state the condition on which the bans' benefit depends", "prove that cotton totes are always worse than plastic bags", "bring in a new argument about harm to wildlife", "reject plastic bag bans altogether"], "answer": 0, "explanation": "After raising problems with totes, the author says the bans are not wrong and that their value depends on reusing bags for a long time. This limits the criticism rather than rejecting the bans.", "difficulty": "hard", "source": "IBPS PO · SBI PO · CDS pattern"},
  {"id": "eng-reading-comprehension-16", "question": "Passage: The old merchant was not a man given to sentiment. He kept careful accounts, paid his workers on the exact day and expected the same exactness in return. Yet when a fire gutted the shop of his chief rival, he was the first to arrive with carts of timber and cloth, and he refused all talk of repayment. Asked why, he said only that a bazaar with one shop is not a bazaar but a monopoly, and that monopolies make men lazy. His neighbours could never decide whether this was generosity dressed as calculation, or calculation dressed as generosity. Question: The neighbours' uncertainty arises because the merchant's action:", "options": ["could be explained either by kindness or by self-interest", "ruined his own business", "broke the rules of the bazaar", "went against his habit of keeping exact accounts"], "answer": 0, "explanation": "Helping a rival looks generous, but his reason (competition keeps him from getting lazy) sounds calculating, so the act fits both motives. Nothing suggests it broke rules or ruined him.", "difficulty": "hard", "source": "IBPS PO · SBI PO · CDS pattern"},
  {"id": "eng-reading-comprehension-17", "question": "Passage: A survey found that people who drink green tea daily report fewer colds than those who do not. A tea company has used the finding in advertisements claiming that green tea 'boosts immunity'. But the survey also showed that daily green-tea drinkers were more likely to exercise, less likely to smoke and, on average, slept an hour longer each night. Any of these habits could explain the difference. Until a trial compares similar people who are randomly assigned to drink or not drink tea, the advertisement claims more than the evidence allows. Question: The author's main criticism of the advertisement is that it:", "options": ["misreports the survey's numbers", "relies on too small a survey", "ignores the side effects of green tea", "treats a correlation as proof of cause without ruling out other factors"], "answer": 3, "explanation": "The author says exercise, not smoking or longer sleep could explain the fewer colds, so the advert jumps from correlation to cause. Survey size and side effects are never raised.", "difficulty": "hard", "source": "IBPS PO · SBI PO · CDS pattern"},
  {"id": "eng-reading-comprehension-18", "question": "Passage: Every spring the hillside above our town turns a pale violet, and every spring the newspapers send photographers. The flowers belong to an invasive shrub that escaped from an old botanical garden and is steadily choking the native grasses that once fed cattle. Graziers have watched their pastures shrink by a third. The photographs, of course, show none of this: only couples posing in a lavender haze. It is hard to blame the visitors. Beauty is persuasive. But a landscape can be lovely and dying at the same time, and the second fact deserves at least as much attention as the first. Question: The author's attitude towards the newspaper coverage is best described as:", "options": ["mildly critical", "furious", "enthusiastic", "indifferent"], "answer": 0, "explanation": "The author notes that the photographs leave out the damage and asks that it get equal attention, while saying it is 'hard to blame the visitors'. That is mild criticism, not fury.", "difficulty": "hard", "source": "IBPS PO · SBI PO · CDS pattern"},
  {"id": "eng-reading-comprehension-19", "question": "Passage: The Indian Ocean Dipole is a difference in sea-surface temperature between the western and eastern parts of the Indian Ocean. In a positive phase, waters near East Africa are warmer than usual while those near Indonesia are cooler; in a negative phase, the pattern reverses. A positive dipole tends to bring heavier rain to East Africa and the Indian subcontinent and drier conditions to Australia. Forecasters watch it closely alongside El Niño in the Pacific, because a positive dipole can partly offset the drying effect that El Niño usually has on the Indian monsoon. Question: The passage answers which of the following questions?", "options": ["In which year was the strongest dipole recorded?", "What causes the dipole to switch from one phase to the other?", "How can a positive dipole affect the Indian monsoon in an El Niño year?", "How often does a positive phase occur?"], "answer": 2, "explanation": "The last sentence says a positive dipole can partly offset El Niño's drying effect on the monsoon. The causes, frequency and record years of the dipole are not discussed.", "difficulty": "hard", "source": "IBPS PO · SBI PO · CDS pattern"},
  {"id": "eng-reading-comprehension-20", "question": "Passage: Meera had rehearsed the speech for a week. She knew where to pause, where to look up, where the audience would laugh. When she reached the stage and the microphone shrieked, she laughed first, before anyone else could, and said, 'Well, at least it's awake.' The hall relaxed. Afterwards her teacher told her the speech had been good but the recovery had been better. Meera, who had expected praise for the lines she had polished so carefully, was not sure whether to feel flattered or slightly cheated. Question: Meera's mixed feelings at the end arise because:", "options": ["the microphone failure ruined her speech", "she was praised more for an unplanned moment than for her careful preparation", "her teacher criticised the speech", "the audience did not laugh at her jokes"], "answer": 1, "explanation": "The teacher valued her quick recovery above the speech she had rehearsed for a week, so she felt both flattered and cheated. The teacher actually called the speech good.", "difficulty": "hard", "source": "IBPS PO · SBI PO · CDS pattern"},
  {"id": "eng-reading-comprehension-21", "question": "Passage: The new manager's first weeks were marked by a studied informality. She ate in the canteen, learned the names of the cleaning staff and left her door open. Some employees found this refreshing; others, more cynical, noticed that every conversation seemed to end with a question about who was doing what, and how well. By the end of the quarter two departments had been merged and three senior posts abolished. Those who had called her approachable now called her shrewd, though it is possible she was both. Question: The phrase 'studied informality' suggests an informality that was:", "options": ["academic in nature", "deliberate and calculated", "learned from management books", "careless and accidental"], "answer": 1, "explanation": "'Studied' here means carefully planned. Her friendly manner also helped her gather information before restructuring. Reading it as 'learned from books' or 'academic' confuses it with studying.", "difficulty": "hard", "source": "IBPS PO · SBI PO · CDS pattern"},
  {"id": "eng-reading-comprehension-22", "question": "Passage: Our city's planners propose to widen the main road from four lanes to six to cut congestion. Experience elsewhere should give them pause. When roads are widened, journeys become quicker for a while, and that very speed attracts drivers who previously took buses, travelled at other hours or did not make the trip at all. Within a few years traffic usually returns to its old level, now spread across six lanes instead of four. Transport economists call this induced demand. If the aim is to move more people, the money might do more good in buses and safe footpaths. Question: The author's argument assumes that:", "options": ["what happened in other cities will also happen in this city", "congestion cannot be reduced by any measure", "buses cost less to run than footpaths", "nobody in the city now travels by bus"], "answer": 0, "explanation": "The author predicts the city's result from 'experience elsewhere', which works only if this city behaves like those cities. That link is never stated, so it is the hidden assumption. The author suggests buses as a fix, so 'no measure works' contradicts the passage.", "difficulty": "hard", "source": "IBPS PO · SBI PO · CDS pattern"},
  {"id": "eng-reading-comprehension-23", "question": "Passage: For most of the twentieth century, scientists believed that adult brains could not grow new neurons. Studies in birds first challenged this view: canaries were found to produce new brain cells each season as they learned new songs. Later research found new neurons in the hippocampus of adult rodents and, more controversially, of humans. How much new growth happens in adult humans is still debated, with some laboratories reporting it into old age and others finding little after childhood. What is no longer seriously argued is that the adult brain is fixed; even where new cells are scarce, existing connections are constantly rewired. Question: Which statement best reflects the current position described in the passage?", "options": ["Humans grow new neurons throughout life, just as canaries do", "The adult brain cannot change after childhood", "Growth of new neurons was first discovered in humans", "Whether adults grow many new neurons is disputed, but the brain's capacity to change is accepted"], "answer": 3, "explanation": "The passage says the amount of adult neuron growth is still debated, but nobody now argues that the brain is fixed. The canary option treats a disputed point as settled, and the first discoveries were in birds.", "difficulty": "hard", "source": "IBPS PO · SBI PO · CDS pattern"},
  {"id": "eng-reading-comprehension-24", "question": "Passage: A shopkeeper who sells umbrellas does well in the rainy season and badly in summer; one who sells sunglasses has the opposite problem. If the two merge their shops, their combined income becomes far steadier, even though neither has sold an extra item. This, in miniature, is the logic of diversification. An investor who holds assets that tend to rise and fall at different times can reduce the swings in the value of the whole collection without necessarily lowering the average return. The trick lies not in owning many things, but in owning things that do not all move together. Question: The umbrella and sunglasses example is used to show that:", "options": ["owning a large number of assets guarantees safety", "seasonal businesses should be avoided", "merging two shops always increases total sales", "combining activities whose fortunes move in opposite directions reduces overall ups and downs"], "answer": 3, "explanation": "The merged shop has steadier income because the two businesses do well in different seasons. The passage says no extra items are sold and that owning many things is not the trick.", "difficulty": "hard", "source": "IBPS PO · SBI PO · CDS pattern"},
  {"id": "eng-reading-comprehension-25", "question": "Passage: Bioluminescence, the production of light by living things, is rare on land but common in the deep sea, where sunlight never reaches. The light is produced when an enzyme, luciferase, acts on a molecule called luciferin in the presence of oxygen. Deep-sea creatures use it in many ways: anglerfish dangle a glowing lure to attract prey, some squid release clouds of glowing ink to confuse predators, and many small shrimps light up their undersides to match the faint glow from above, so that a hunter looking up sees no silhouette. On land, fireflies use their flashes mainly to find mates. Question: How many of the following statements are supported by the passage? I. Luciferase is the molecule that is acted upon to produce light. II. Some animals use light to hide rather than to be seen. III. Fireflies use light chiefly to attract prey. IV. Oxygen is needed for the light-producing reaction.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "II is supported (shrimps light their undersides so they cast no silhouette) and IV is supported (the reaction needs oxygen). I swaps the roles, because luciferase is the enzyme and luciferin is the molecule acted upon. III is wrong, because fireflies flash mainly to find mates. So only two are supported.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · CDS pattern"},
  {"id": "eng-reading-comprehension-26", "question": "Passage: A software firm that switched to a four-day week, without cutting pay, reports that output per employee did not fall and that staff took fewer sick days. Its chief executive now urges all companies to follow. Critics point out that the firm made the change after a year of strong profits and that its employees, mostly young programmers, work on tasks that can be finished anywhere and at any hour. A hospital, a factory line or a bus depot, they say, cannot simply close for a day. Question: Which of the following, if true, would most strengthen the critics' position?", "options": ["Many programmers prefer to work from home", "The firm's employees reported higher job satisfaction after the change", "The firm's profits rose further in the year after the change", "Hospitals that tried shorter working weeks had to hire many more staff to keep wards open"], "answer": 3, "explanation": "The critics say the firm's result will not carry over to round-the-clock services. Evidence that hospitals needed far more staff to make it work supports exactly that. Higher satisfaction and rising profits back the chief executive instead.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · CDS pattern"},
  {"id": "eng-reading-comprehension-27", "question": "Passage: Of the roughly seven thousand languages spoken today, linguists estimate that around forty per cent are endangered, many with fewer than a thousand speakers. A language rarely dies because its speakers are forbidden to use it; more often, parents decide that their children will get better jobs in a dominant language and stop speaking the old one at home. Within two generations, the grandparents may be the last fluent speakers. Revival is difficult but not impossible: Hebrew, once used mainly in prayer and scholarship, became the everyday language of millions in the twentieth century, and efforts in Wales and New Zealand have increased the number of young speakers of Welsh and Maori. Question: Each of the following can be inferred from the passage EXCEPT:", "options": ["Economic considerations can lead families to give up their own language", "Most endangered languages are dying because governments have banned them", "A language that has stopped being used in daily life can regain everyday use", "Passing a language on at home is crucial to its survival"], "answer": 1, "explanation": "The passage says a language 'rarely' dies because it is forbidden; it usually fades when parents stop using it for economic reasons. The other three follow from the text, and the Hebrew example shows a language returning to daily use.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · CDS pattern"},
  {"id": "eng-reading-comprehension-28", "question": "Passage: Critics dismissed her first exhibition as the work of a hobbyist; her bold, flat colours seemed childish beside the subtle shading then in fashion. She did not argue. For twenty years she painted in a rented room above a tailor's shop, selling just enough to pay the rent. When a younger generation rediscovered her canvases, the same newspapers that had mocked her hailed her as a pioneer. Asked in an interview whether she felt vindicated, she replied that she had been too busy painting to keep score. Question: Her reply in the interview suggests that she was:", "options": ["doubtful about the merit of her early style", "quietly vindicated and eager to say so", "resentful but too proud to show it", "unconcerned with the verdicts of critics and absorbed in her work"], "answer": 3, "explanation": "'Too busy painting to keep score' shows she paid little attention to praise or blame and simply kept working, as she had for twenty years without arguing. Nothing suggests resentment, eagerness for credit or doubt about her style.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · CDS pattern"},
  {"id": "eng-reading-comprehension-29", "question": "Passage: Antibiotics kill bacteria or stop them from multiplying, but they do not work against viruses. When a patient takes an antibiotic, the drug kills the susceptible bacteria first; any cells that happen to carry a resistance gene survive and multiply. Bacteria can also pass resistance genes to one another, even across species, on small rings of DNA called plasmids. Each unnecessary prescription, for instance for a common cold, therefore gives resistant strains an opportunity without offering any benefit. Large amounts of antibiotics are also given to farm animals to make them grow faster, adding further pressure. Question: How many of the following can be inferred from the passage? I. An antibiotic prescribed for a common cold brings no benefit because the cold is caused by a virus. II. Resistance genes can pass only from parent bacteria to their offspring. III. Antibiotic use on farms adds to the selection of resistant bacteria. IV. Resistant bacteria survive treatment because they already carried the gene, not because the drug created it.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I follows from 'no benefit' for a cold together with 'do not work against viruses'. III follows from the farm sentence. IV follows from cells that 'happen to carry' the gene surviving. II is contradicted, because plasmids pass genes between bacteria, even across species. So three can be inferred.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · CDS pattern"},
  {"id": "eng-reading-comprehension-30", "question": "Passage: Some historians argue that the printing press caused the Protestant Reformation. The claim has an obvious appeal: Luther's pamphlets were printed in hundreds of thousands of copies and spread across Germany within weeks. But earlier reformers, such as Jan Hus a century before, had attracted large followings without print, and the press also served the Catholic side, which printed its own replies in great numbers. A better way to put it may be that print changed the speed and scale of the quarrel, while the grievances that fuelled it had been building for generations. Question: Which best describes the organisation of the passage?", "options": ["The events of the Reformation are narrated in chronological order", "A claim is stated, evidence against its strong form is given, and a more limited version is proposed", "A theory is stated and then fully confirmed with examples", "The views of two historians are compared and both are rejected"], "answer": 1, "explanation": "The passage states the claim that print caused the Reformation, offers Hus and Catholic printing as objections, and ends with a narrower claim (print changed the speed and scale). It does not simply confirm or reject the theory.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · CDS pattern"},
  {"id": "eng-reading-comprehension-31", "question": "Passage: The company won its long legal battle against the small start-up that had copied its design. The court awarded damages, and the company's lawyers celebrated. But the case had dragged on for six years, cost several times the damages awarded and produced a stream of headlines portraying the company as a bully crushing a pair of young inventors. Its sales among younger buyers fell steadily over the same period. Inside the boardroom, at least one director described the outcome as a Pyrrhic victory. Question: By calling it a 'Pyrrhic victory', the director meant that the win:", "options": ["was celebrated before the verdict was announced", "was obtained by unfair means", "was likely to be overturned on appeal", "cost so much that it was hardly worth winning"], "answer": 3, "explanation": "A Pyrrhic victory is one gained at such a cost that it is nearly a defeat. Here the legal costs ran several times the damages and the company's image and sales suffered. Nothing suggests unfair means or an appeal.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · CDS pattern"},
  {"id": "eng-reading-comprehension-32", "question": "Passage: The government plans to raise the tax on sugary drinks, arguing that higher prices will reduce consumption and so lower rates of diabetes. Drink makers reply that consumers will simply switch to cheaper brands or to sweets, leaving their sugar intake unchanged. Evidence from countries that introduced similar taxes is mixed: purchases of taxed drinks fell noticeably, but few studies have yet tracked whether total sugar intake or diabetes rates changed. Health experts add that diabetes has several causes, including inactivity and family history. Question: Which of the following is implicit in the government's argument? I. Demand for sugary drinks responds to price. II. Sugary drinks are the only cause of diabetes.", "options": ["Only I", "Only II", "Both I and II", "Neither I nor II"], "answer": 0, "explanation": "The government expects higher prices to cut consumption, which assumes demand responds to price (I). Its argument needs sugary drinks to be one cause of diabetes, not the only one, so II is too extreme.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · CDS pattern"},
  {"id": "eng-reading-comprehension-33", "question": "Passage: In 2010 a town of 50,000 people had 10,000 registered cars. By 2020 the population had grown to 60,000 and the number of cars to 18,000. The council's report celebrates the fact that the share of residents using the bus rose from 20 per cent to 22 per cent over the same decade. A local newspaper, however, notes that roads are far more crowded than before and that the bus network has not added a single route in ten years. Both sides claim the figures prove their point. Question: Which conclusion is best supported by the figures in the passage?", "options": ["Cars per person rose by half, so the small rise in the bus share has not kept up with growing car use", "The number of bus users fell during the decade", "The town's population grew faster than its number of cars", "Cars per person rose by 80 per cent"], "answer": 0, "explanation": "Cars per 1,000 people went from 10,000 ÷ 50 = 200 to 18,000 ÷ 60 = 300, a 50% rise. Bus users went from 10,000 to 13,200, so they rose rather than fell. 80% is the rise in the total number of cars, not cars per person, and population grew only 20% against 80% for cars.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · CDS pattern"},
  {"id": "eng-reading-comprehension-34", "question": "Passage: I grew up in a town that the new expressway has turned into a suburb of the city. My mother can reach the hospital in twenty minutes instead of two hours, and my nephews can take jobs that did not exist when I left. I am glad of all this. I am also aware that the mango orchard where we spent our summers is a warehouse now, that the river ghat is fenced off, and that the bazaar sells exactly what every other bazaar sells. When people ask whether the expressway has been good for the town, I find I cannot give them a single answer. Question: The author's attitude towards the change in the town is best described as:", "options": ["nostalgic", "resentful", "ambivalent", "apathetic"], "answer": 2, "explanation": "The author is glad of faster hospital trips and new jobs but regrets the lost orchard and ghat, and cannot give 'a single answer'. That mix is ambivalence. 'Nostalgic' covers only the regret and leaves out the gladness.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · CDS pattern"},
  {"id": "eng-reading-comprehension-35", "question": "Passage: Archaeologists digging at a coastal site found many fish bones in the lowest layers, dated to about 6000 BCE, and almost none in the layers above, dated to about 5000 BCE, where the bones of goats and cattle dominate. One team concludes that the inhabitants gave up fishing because they took up herding. Another suggests that the sea retreated during that thousand years, leaving the settlement several kilometres inland and making fishing impractical, after which the people turned to herding. Question: Which finding would most support the second team's view over the first?", "options": ["Herding was practised in nearby inland villages by 5500 BCE", "Fishing hooks were found in the lowest layers", "Goat bones in the upper layers show signs of butchery", "Sediment cores show the shoreline moved several kilometres seaward between 6000 and 5000 BCE"], "answer": 3, "explanation": "The second team's view rests on the sea having retreated, and sediment cores showing the coastline moving away confirm that directly. Butchered goats and fishing hooks fit both views, and nearby herding, if anything, supports the first team.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · CDS pattern"},
  {"id": "eng-reading-comprehension-36", "question": "Passage: Cities are often hotter than the countryside around them, sometimes by several degrees at night. Dark roofs and roads absorb sunlight during the day and release the heat after dark; tall buildings trap warm air and block breezes; and air conditioners pump heat from inside buildings into the streets. The effect is not merely uncomfortable. During heat waves it raises death rates among the elderly and the poor, who are least able to escape it. Remedies are known and often cheap: painting roofs white, planting trees along streets and keeping open water bodies can all lower local temperatures. Question: Which of the following best summarises the passage?", "options": ["Cities are hotter than villages only during the day", "Cities trap heat because of how they are built and run, which endangers vulnerable people, but simple measures can reduce it", "Planting trees is the only way to cool a city", "Air conditioners are the main cause of high temperatures in cities"], "answer": 1, "explanation": "The summary has to cover the causes, the danger to the vulnerable and the cheap remedies. The other options overstate one cause or one remedy, or contradict the passage, which stresses that cities stay hotter at night.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · CDS pattern"},
  {"id": "eng-reading-comprehension-37", "question": "Passage: The judge was known for her temper, not in the sense of anger, but of balance. She could temper a harsh law with a merciful sentence, yet she never let sympathy blunt the edge of a ruling that the facts demanded. Lawyers who appeared before her learned to prepare thoroughly, because she had little patience for arguments that leaned on emotion rather than evidence. When she retired, colleagues remembered her less for any single judgment than for the steadiness she brought to every one. Question: In the passage, 'temper' in its first use and 'temper' in its second use mean, respectively:", "options": ["mood; strengthen", "composure; provoke", "composure; soften", "anger; harden"], "answer": 2, "explanation": "The first 'temper' is a noun meaning calm balance or composure (the passage rules out anger). The second is a verb meaning to soften or moderate, as in softening a harsh law with mercy.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · CDS pattern"},
  {"id": "eng-reading-comprehension-38", "question": "Passage: The Great Barrier Reef stretches for more than 2,300 kilometres off the coast of Queensland, Australia, and is made up of about 3,000 individual reefs. Its corals live in partnership with tiny algae that supply them with food through photosynthesis and give them their colours. When the water stays unusually warm for several weeks, the corals expel the algae and turn white, an event called bleaching. Bleached corals are not dead and can recover if temperatures fall soon enough; prolonged heat, however, starves them. Mass bleaching struck the reef in 1998, 2002, 2016 and 2017, among other years. Question: Which question CANNOT be answered from the passage?", "options": ["Can bleached corals recover?", "Why do corals turn white when they bleach?", "How do the algae benefit the corals?", "What percentage of the reef's coral died in 2016?"], "answer": 3, "explanation": "The passage gives bleaching years but no death figures. It does explain whitening (the coloured algae are expelled), recovery (possible if the water cools soon) and the benefit (food from photosynthesis).", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · CDS pattern"},
  {"id": "eng-reading-comprehension-39", "question": "Passage: Many early European maps of distant lands filled their unknown interiors with drawings of animals and invented mountain ranges. Later mapmakers, more cautious, began to leave such regions blank. A blank space looked like a confession of ignorance, and some patrons disliked it. Yet it had a practical virtue: a traveller who saw a white patch knew he was entering country no outsider had charted, while one who trusted an invented mountain range might plan a route around obstacles that did not exist, or march confidently towards a lake that was not there. Question: Which of the following is the closest modern parallel to the virtue the passage praises?", "options": ["A weather forecast that states the chance of rain as a percentage instead of confidently promising rain", "A textbook that adds more pictures to each chapter", "A satellite image in which cloudy patches are filled in with guessed terrain", "A map app that shows more restaurants in each area"], "answer": 0, "explanation": "The blank map was useful because it honestly showed the limits of knowledge. A forecast that states its uncertainty does the same. A satellite image that fills gaps with guesses repeats the invented-mountain error.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · CDS pattern"},
  {"id": "eng-reading-comprehension-40", "question": "Passage: Gardeners in dry regions are often advised to water deeply but rarely, rather than a little every day. Frequent shallow watering keeps only the top few centimetres of soil moist, so roots stay near the surface, where the soil dries fastest in hot weather. Deep, infrequent watering sends moisture far down, and roots follow it. A plant with deep roots can survive a week of heat that would wilt its shallow-rooted neighbour, even though both received the same total amount of water. Question: Which situation follows the same principle as the one described?", "options": ["A student revises the same chapter for five minutes every day", "A coach gives athletes occasional long, demanding sessions rather than many short, easy ones, so they can cope with gruelling races", "A farmer doubles the total water given to his crop to raise the yield", "A city adds more taps so that residents need not walk far for water"], "answer": 1, "explanation": "The principle is that the same total input, given in fewer, deeper doses, builds resilience for hard times, just as deep roots survive a heat wave. Long, demanding training sessions build endurance the same way. Doubling the total water changes the amount rather than how it is given.", "difficulty": "very-hard", "source": "IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-41","question":"Passage: For centuries, the stepwells of western India were far more than places to draw water. Built with long flights of stone steps leading down to the water table, they allowed people to reach water even when the level dropped sharply in summer. Because the lower chambers stayed several degrees cooler than the surface, travellers rested there during the hottest hours, and women gathered to talk while filling their pots. Many stepwells were richly carved with gods, dancers and floral patterns, turning a practical structure into a work of art. When piped water arrived in the twentieth century, most stepwells were abandoned and filled with rubbish. Today, a few have been cleaned and restored, and they attract tourists and local families alike, reminding visitors that engineering and beauty once went hand in hand. Question: The passage is mainly about:","options":["the many roles stepwells played and how they fell into neglect","the techniques used to carve stone sculptures","why piped water is better than well water","the tourist industry in western India"],"answer":0,"explanation":"The passage describes the practical, social and artistic roles of stepwells, their abandonment and partial revival. Carving and tourism are only details.","difficulty":"easy","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-42","question":"Passage: Street vendors are often treated as a nuisance by city authorities. They are accused of blocking pavements, creating litter and avoiding taxes. Yet millions of people depend on them every day for cheap meals, vegetables and household goods, and the vendors themselves are frequently migrants with no other source of income. A law passed in India in 2014 tried to strike a balance by asking cities to survey vendors, issue certificates and set aside vending zones. Where it has been implemented sincerely, vendors no longer live in fear of sudden evictions, and pavements have become more orderly. Where it has been ignored, the old cycle of raids, bribes and returns continues. The problem, it seems, lies less in the law than in the will to apply it. Question: According to the passage, where the law has been ignored:","options":["pavements have become more orderly","vendors have voluntarily moved to vending zones","raids, bribes and the vendors' return keep repeating","city authorities have stopped collecting taxes"],"answer":2,"explanation":"The passage says that where the law is ignored 'the old cycle of raids, bribes and returns continues'. Orderly pavements are reported where the law IS implemented.","difficulty":"easy","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-43","question":"Passage: My grandmother learned to read at the age of sixty-two. As a girl she had been kept at home to look after her younger brothers, and for most of her life she signed documents with a thumbprint, a fact that embarrassed her more than she ever admitted. When the village started an evening class for adults, she was the first to enrol and the last to leave each night. She practised letters on the backs of old calendars and made us children test her on the signboards at the bus stand. The day she read a whole page of the newspaper aloud, slowly but without help, she did not smile; she simply folded the paper, put it under her pillow and said she would read the rest tomorrow. Question: Which word best describes the grandmother as presented in the passage?","options":["resentful","careless","boastful","determined"],"answer":3,"explanation":"She enrols first, stays last, practises daily and quietly plans to read more — signs of determination. She does not boast even after succeeding.","difficulty":"easy","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-44","question":"Passage: Weather forecasting has improved remarkably in the last few decades. A five-day forecast today is about as accurate as a one-day forecast was in the 1980s. The gains come from three sources: satellites that watch the whole planet continuously, faster computers that can run more detailed models of the atmosphere, and better methods of feeding fresh observations into those models. Even so, the weather remains a chaotic system, in which tiny errors in the starting data grow larger over time. That is why forecasters now issue predictions as probabilities — a 70 per cent chance of rain — rather than as certainties. Far from being a sign of weakness, such honesty about uncertainty helps farmers, fishermen and disaster managers make better decisions. Question: As used in the passage, the word 'chaotic' refers to a system in which:","options":["events happen without any physical cause","small differences at the start lead to large differences later","nothing can ever be predicted at all","only satellites can collect useful data"],"answer":1,"explanation":"The passage defines it in the next clause: tiny errors in the starting data grow larger over time. It does not claim that weather is causeless or wholly unpredictable.","difficulty":"easy","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-45","question":"Passage: Composting at home is easier than most people imagine. Vegetable peels, tea leaves, eggshells and dry leaves can be layered in a simple container with a few holes for air. Within six to eight weeks, microbes break this material down into dark, crumbly compost that enriches garden soil. The main rules are to keep the heap moist but not soggy, to turn it every week so that air reaches the inside, and to avoid adding meat or oily food, which attract pests and produce bad smells. A household that composts its kitchen waste can cut the rubbish it sends to landfills by nearly half. In cities where landfills are already overflowing, such small habits, repeated across thousands of homes, can make a visible difference. Question: Which of the following should NOT be added to a home compost heap, according to the passage?","options":["Meat and oily food","Tea leaves","Eggshells","Dry leaves"],"answer":0,"explanation":"The passage says to avoid meat and oily food because they attract pests and cause smells. The other three are listed as suitable materials.","difficulty":"easy","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-46","question":"Passage: For many small farmers, the diesel pump was both a blessing and a burden. It lifted water from wells to the fields, but fuel was expensive and often had to be carried from a town many kilometres away. Solar pumps promise to change this. Once installed, they run on free sunlight, need little maintenance and make no noise or smoke. Government subsidies have brought the cost within reach of many farmers. There is, however, a risk that experts have begun to point out: because pumping now costs almost nothing, some farmers run their pumps all day, drawing more groundwater than the land can replenish. Unless free energy is matched by careful water management, the solar revolution could simply dry up the wells faster. Question: The 'risk' mentioned in the passage is that solar pumps may:","options":["pollute the air around fields","break down frequently","be too expensive for farmers","encourage overuse of groundwater"],"answer":3,"explanation":"Because pumping becomes almost free, farmers may draw more groundwater than can be replenished. The passage states the pumps need little maintenance and make no smoke.","difficulty":"easy","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-47","question":"Passage: When a computer program defeated the world chess champion in 1997, many people predicted the death of the game. Why would anyone play chess if a machine could always win? The opposite happened. Chess is more popular today than ever before. Players use computers to analyse their games, spot mistakes and prepare new openings. Young players in small towns, with no coach nearby, can now practise against strong opponents at any hour. Online platforms broadcast tournaments to millions of viewers, with engines showing who is winning after each move. The machines did not replace human players; they became their tireless teachers. The story of chess suggests that a technology that outperforms people can still enrich, rather than end, a human activity. Question: What happened to chess after a computer defeated the world champion?","options":["Most professional players gave up the game","It was replaced by computer-only tournaments","It became more popular than before","It was banned on online platforms"],"answer":2,"explanation":"The passage says 'The opposite happened. Chess is more popular today than ever before.' Computers became teachers rather than replacements.","difficulty":"easy","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-48","question":"Passage: Elephants need space. A single herd may roam hundreds of square kilometres in a year, following water and food through the seasons. As forests have been broken up by roads, railways, canals and farms, elephants increasingly find their old paths blocked. When they push through, they trample crops and sometimes kill people, and angry villagers retaliate. Wildlife corridors — narrow strips of protected land that link one forest patch to another — offer a solution. They let elephants move between habitats without wandering into villages. Securing corridors is not easy: the land is often privately owned, and families must be compensated fairly for moving. But experience shows that a well-planned corridor costs far less than the endless cycle of crop damage, compensation claims and deaths that it prevents. Question: According to the passage, a wildlife corridor is:","options":["a fence that keeps elephants away from roads","a strip of protected land connecting separate forest areas","a zoo where injured elephants are treated","a compensation scheme for farmers"],"answer":1,"explanation":"The passage defines corridors as 'narrow strips of protected land that link one forest patch to another'.","difficulty":"easy","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-49","question":"Passage: Most students prepare for exams by reading their notes again and again. It feels productive, because the material becomes familiar. But familiarity is not the same as memory. Research on learning shows that two simple changes work far better. The first is testing oneself: closing the book and trying to recall what one has read, even if the attempt fails. The second is spacing: reviewing a topic after a day, then after a few days, then after a week, instead of cramming it all at once. Both methods feel harder than rereading, and that very difficulty is what strengthens memory. Students who adopt them often report that they study for fewer hours but remember more on the day of the exam. Question: According to the passage, why does rereading feel productive?","options":["Because the material starts to feel familiar","Because it strengthens memory the most","Because it is harder than self-testing","Because it requires fewer hours of study"],"answer":0,"explanation":"Rereading feels productive because 'the material becomes familiar', but the passage warns that familiarity is not memory.","difficulty":"easy","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-50","question":"Passage: The old lighthouse keeper still climbs the hundred and twelve steps every evening, though the lamp has been automatic for eleven years. Nobody pays him to do it. The government that once employed him now sends a technician twice a year to check the bulbs and the solar panels, and the technician, a cheerful young man, always finds everything in order. 'Of course it is in order,' the old man tells him. 'I wipe the glass every night.' The technician laughs, but he has noticed that the lamp at this lighthouse never seems to need the repairs that lamps at the other, empty lighthouses do. In his report he writes only 'Satisfactory'. He does not know how to write down an old man's habit. Question: The keeper continues to climb the steps every evening mainly because:","options":["the lamp must be switched on by hand","the government still pays him for it","it is a lifelong habit and a matter of personal care","the technician has asked him to do so"],"answer":2,"explanation":"The lamp is automatic and nobody pays him; he goes out of habit and care ('I wipe the glass every night').","difficulty":"easy","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-51","question":"Passage: Folk theatre in many parts of India once travelled from village to village, performing all night on makeshift stages lit by lanterns. Audiences knew the stories by heart, yet they came every year, because the pleasure lay in how each troupe sang, joked and improvised. Today many of these forms are struggling. Young performers leave for jobs in cities, and audiences prefer television serials that require no late nights. Some troupes have survived by shortening their shows, adding film songs or performing at hotels for tourists. Purists complain that this dilutes the tradition. But traditions have always changed; the forms we now call 'classical' were once new and controversial. The real danger is not change but silence — a stage where nobody performs at all. Question: The author's attitude towards troupes that adapt their performances is best described as:","options":["fearful and alarmed","contemptuous and dismissive","completely indifferent","understanding and broadly accepting"],"answer":3,"explanation":"The author argues that traditions have always changed and that 'the real danger is not change but silence', so he accepts adaptation. It is the purists, not the author, who complain.","difficulty":"moderate","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-52","question":"Passage: Constant noise is usually treated as an irritation rather than a health problem. Yet studies in several countries have linked long-term exposure to traffic noise with higher blood pressure, poorer sleep and even a greater risk of heart disease. The reason seems to be that the body reacts to loud or sudden sounds as if to a threat, releasing stress hormones even while a person is asleep and not consciously aware of the sound. Over years, these repeated small alarms take their toll. Unlike smoke, noise leaves no visible trace, which may explain why it receives so little attention from city planners. Quieter road surfaces, better window insulation and limits on night-time honking are cheap measures that could protect the health of millions. Question: It can be inferred from the passage that noise receives little attention from planners partly because:","options":["it has been proven harmless to sleeping people","its effects are not visible in the way that smoke is","the measures to reduce it are very expensive","people quickly get used to it and stop reacting"],"answer":1,"explanation":"The passage says noise 'leaves no visible trace, which may explain why it receives so little attention'. It describes the remedies as cheap and says the body keeps reacting even during sleep.","difficulty":"moderate","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-53","question":"Passage: India's groundwater crisis began with a success. In the 1970s and 1980s, cheap electric pumps and subsidised power allowed millions of farmers to sink their own borewells. Irrigation was no longer limited to land near canals, and harvests rose. But because each farmer could pump as much as he wanted, and electricity was often free or charged at a flat rate, there was no reason to save water. As water tables fell, farmers drilled deeper, spending more on bigger pumps. In some districts, wells that once struck water at twenty feet now go down several hundred. The individual farmer is not to blame; he is responding sensibly to the incentives before him. It is the incentives that must change, and that is a task for policy, not for preaching. Question: The author holds that the main cause of the groundwater crisis is:","options":["the greed and ignorance of individual farmers","incentives that reward unlimited pumping","the failure of canals to reach most villages","a decline in rainfall over recent decades"],"answer":1,"explanation":"The author explicitly says the farmer 'is not to blame' and that 'it is the incentives that must change' — flat or free power encouraged unlimited pumping.","difficulty":"moderate","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-54","question":"Passage: A shirt that costs less than a cup of coffee seems like a bargain. But the low price hides costs that someone else pays. Growing cotton consumes vast amounts of water; dyeing fabric pollutes rivers near factories; and garment workers, often young women, may earn too little to live on. Because such clothes are cheap, buyers treat them as disposable, wearing them a few times before throwing them away. Most of these garments end up in landfills or are burnt. Some brands now promise 'sustainable' collections, but critics point out that a brand selling ever larger volumes of clothing cannot be sustainable merely by changing the fabric. The most sustainable shirt, they say, is the one already in your wardrobe. Question: The critics' view of 'sustainable' collections is that:","options":["they use more water than cotton clothes","they are more expensive than ordinary clothes","they cannot solve the problem while sales volumes keep rising","they are the best solution available today"],"answer":2,"explanation":"Critics say a brand selling 'ever larger volumes' cannot be sustainable merely by changing the fabric; the root problem is overconsumption.","difficulty":"moderate","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-55","question":"Passage: Look up on a clear night in any large city and you will see perhaps a dozen stars. A few generations ago, the same sky would have shown thousands, with the Milky Way stretching across it like a pale river. The difference is not in the sky but in the ground: street lamps, billboards and buildings spill so much light upwards that the darkness is washed away. This light pollution does more than spoil the view. Migrating birds, which navigate partly by the stars, become confused and crash into lit towers; baby turtles, which crawl towards the brightest horizon, head inland instead of to the sea. Fortunately, light pollution is easier to fix than most kinds. Shielded lamps that point downwards save energy as well as the night. Question: The author's statement that light pollution is 'easier to fix than most kinds' most likely rests on the fact that:","options":["simple changes to lamp design reduce it immediately","birds and turtles are adapting to it","most cities have already banned street lamps","it disappears on its own during winter"],"answer":0,"explanation":"The passage follows the claim with the remedy: shielded lamps that point downwards. Unlike, say, chemical pollution, nothing lingers once the light is redirected.","difficulty":"moderate","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-56","question":"Passage: Children learn best in a language they understand. That seems obvious, yet in many schools young children are taught in a language they rarely hear at home. They spend the early years memorising words they cannot follow, and many fall behind permanently. Studies show that pupils who begin in their mother tongue and then move gradually to a second language often end up better in both languages than those who start directly in the second. The reason is that reading and reasoning, once learnt in a familiar language, transfer easily. Parents, however, often prefer English-medium schools because they see English as the key to good jobs. The challenge for policy is to respect that hope without sacrificing the foundation on which all learning rests. Question: Which of the following best describes the 'challenge for policy' mentioned at the end?","options":["Teaching all children only in their mother tongue throughout school","Persuading parents that English is unnecessary for jobs","Abolishing English-medium schools entirely","Balancing parents' wish for English with children's need to learn first in a familiar language"],"answer":3,"explanation":"The final sentence speaks of respecting parents' hope (English for jobs) without sacrificing the foundation (mother-tongue learning). It does not reject English.","difficulty":"moderate","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-57","question":"Passage: Delivery riders and cab drivers who work through apps are called 'partners' rather than employees. The label matters. As partners, they can choose their hours and log out whenever they like, which many value. But they also lack the protections employees enjoy: there is no paid leave, no health insurance from the company and no pension. If a rider is injured in an accident, the cost often falls on him alone. Companies argue that treating riders as employees would destroy the flexibility that attracts them. Workers' groups respond that flexibility and security are not opposites; a fund paid for by a small charge on every order could provide insurance without forcing anyone to work fixed hours. Such funds, they add, already exist for some other informal trades. Question: The workers' groups' proposal is intended to show that:","options":["companies should stop charging for deliveries","riders should be made full-time employees","security can be provided without removing flexibility","flexibility is not valued by most riders"],"answer":2,"explanation":"They argue 'flexibility and security are not opposites' and propose an order-based fund that insures riders without fixed hours.","difficulty":"moderate","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-58","question":"Passage: Turning seawater into drinking water sounds like the perfect answer to water shortages. The technology already exists: in reverse osmosis, seawater is pushed at high pressure through membranes that hold back the salt. Several coastal cities depend on such plants. Yet desalination has drawbacks that make it a last resort rather than a first choice. It uses a great deal of energy, which makes the water expensive and, if the power comes from coal, adds to carbon emissions. The leftover brine, twice as salty as seawater, is usually pumped back into the sea, where it can harm marine life near the outlet. For inland towns, the cost of piping water uphill from the coast adds further to the bill. Fixing leaking pipes is usually far cheaper. Question: The author's view of desalination is that it is:","options":["harmless to the environment if done properly","the perfect answer to all water shortages","a technology that has not yet been tested","useful but costly, best used when other options are exhausted"],"answer":3,"explanation":"The author calls it 'a last resort rather than a first choice' because of energy use, cost and brine. The 'perfect answer' view is the one he qualifies.","difficulty":"moderate","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-59","question":"Passage: Loneliness among the elderly is often described as a private sorrow. Increasingly, doctors treat it as a public health problem. People who are chronically lonely tend to sleep badly, eat poorly and visit doctors more often; some studies suggest that loneliness harms health as much as smoking a pack of cigarettes a day. The causes are partly modern: children move to distant cities for work, joint families give way to nuclear ones, and neighbourhoods change faster than old friendships can adjust. Some towns now run 'befriending' schemes in which volunteers phone or visit elderly people regularly. Such schemes cost little, and early evaluations show that a weekly conversation can lift mood and reduce visits to the doctor. Few medicines are so cheap or so pleasant. Question: The comparison with smoking is used in the passage to:","options":["emphasise how serious the health effects of loneliness can be","argue that elderly people smoke more when lonely","show that smoking causes loneliness","suggest that befriending schemes reduce smoking"],"answer":0,"explanation":"The comparison shows the scale of harm — loneliness may hurt health as much as heavy smoking — supporting the claim that it is a public health issue.","difficulty":"moderate","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-60","question":"Passage: Bamboo is technically a grass, but in many parts of Asia it has long been used as a building material. It grows astonishingly fast — some species several centimetres a day — and can be harvested in three to five years, compared with decades for most timber. Weight for weight, it is remarkably strong in tension, which is why it has been used for scaffolding on high-rise buildings. Its weaknesses are equally real: untreated bamboo rots and attracts insects, and its hollow, irregular stems are hard to join with the precision modern construction demands. Engineers are now developing treated and laminated bamboo products that overcome these problems. If they succeed, a plant once seen as the poor man's timber may become a material of choice. Question: The phrase 'the poor man's timber' suggests that bamboo was traditionally regarded as:","options":["the most valuable building material in Asia","a cheap and inferior substitute for wood","a material used only by the wealthy","too strong to be used for houses"],"answer":1,"explanation":"'Poor man's X' means a cheaper, lesser version of X. The final sentence contrasts this old view with its possible future as 'a material of choice'.","difficulty":"moderate","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-61","question":"Passage: Some cities charge drivers a fee for entering the busiest parts of town during peak hours. The idea, known as congestion pricing, is simple: road space at rush hour is scarce, and when something scarce is free, it gets overused. Where the scheme has been tried, traffic in the charged zone has fallen sharply, buses run faster and air quality has improved. The money collected is often spent on public transport. Critics argue that the charge is unfair to poorer drivers, who may have no alternative. Supporters reply that the poorest residents rarely drive into city centres at all; they ride the very buses that the scheme speeds up. The fairness of the policy, they say, depends on how its revenue is used. Question: The supporters' reply to the critics relies mainly on the point that:","options":["the poorest residents mostly use buses, which benefit from the scheme","poorer drivers can easily afford the charge","the charge applies only to luxury cars","traffic did not actually fall in the charged zone"],"answer":0,"explanation":"Supporters say the poorest rarely drive into the centre and instead ride the buses that the scheme speeds up, so the scheme can help rather than hurt them.","difficulty":"moderate","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-62","question":"Passage: Handloom weaving in India survives on a knife-edge. A sari that takes a weaver two weeks to make by hand must compete with a power-loom copy produced in an hour and sold at a fraction of the price. Most buyers cannot tell the difference, and some sellers are happy to keep it that way. Geographical Indication tags, which certify that a product comes from a particular region and is made by traditional methods, were meant to protect weavers from such imitation. In practice, enforcement is weak, and many weavers do not even know their craft is registered. A label is only as strong as the system that checks it. Without inspections and buyer awareness, the tag risks becoming a decoration rather than a defence. Question: What does the author mean by saying the tag 'risks becoming a decoration rather than a defence'?","options":["It is no longer awarded to handloom products","It is printed in an attractive design","It will increase the price of power-loom saris","It may look official but fail to protect weavers in practice"],"answer":3,"explanation":"Without enforcement and awareness, the GI label would exist on paper ('decoration') without actually shielding weavers from imitation ('defence').","difficulty":"moderate","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-63","question":"Passage: Some universities have begun to experiment with open-book examinations. Students may bring textbooks and notes into the hall, but the questions are designed so that the answers cannot simply be copied. Instead of asking 'Define inflation', a paper might describe a small town's rising prices and ask students to explain what is happening and what the local bank should do. Teachers who have tried this format report that it rewards understanding over memory, and that students prepare differently — less by learning definitions and more by practising how to apply ideas. Students, however, are often surprised to find that open-book papers are harder, not easier. Having the book in front of you is of little use if you do not know what you are looking for. Question: Why do students find open-book papers harder than they expect?","options":["They are not allowed enough time to read their books","The questions test application of ideas, which the book alone cannot supply","The questions ask only for definitions","Teachers do not allow notes in the hall"],"answer":1,"explanation":"Questions are designed so answers cannot be copied; they require applying ideas, and 'having the book ... is of little use if you do not know what you are looking for'.","difficulty":"moderate","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-64","question":"Passage: Every summer the narrow roads of popular hill towns fill with cars. Hotels are booked months in advance, water tankers queue outside guest houses, and the hillsides are scarred by new construction. Tourism brings money and jobs, and few residents want it to stop. But the very crowds that sustain the economy are slowly destroying what the visitors come to see — the cool air, the quiet forests and the views. Some towns have begun to limit the number of vehicles allowed in each day or to charge an environmental fee. Hoteliers protest that such limits will drive tourists elsewhere. Their fear is understandable, yet a hill town that loses its charm will lose its tourists anyway, only more slowly and more painfully. Question: Which of the following best captures the author's response to the hoteliers' protest?","options":["Tourists will never go elsewhere","Hoteliers should be banned from the town","Without limits, the town will lose tourists eventually, and in a worse way","Environmental fees will increase the number of visitors"],"answer":2,"explanation":"The author grants their fear but argues that a town that loses its charm 'will lose its tourists anyway, only more slowly and more painfully'.","difficulty":"moderate","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-65","question":"Passage: Old mobile phones, laptops and chargers contain small amounts of gold, silver and copper, along with toxic lead and mercury. In many Indian cities, this electronic waste is processed not in factories but in small backyard workshops. Workers, often without gloves or masks, break open devices and burn cables to recover metal, breathing in fumes that damage the lungs and nerves. Formal recycling plants exist, but they struggle to get enough waste, because the informal sector pays households more for their old devices. Banning the backyard workshops would put thousands out of work and simply push the trade underground. A more realistic approach, some experts argue, is to bring informal workers into the formal system, training them and supplying safe equipment. Question: Why do formal recycling plants struggle to get enough e-waste?","options":["The government bans the sale of e-waste","Households prefer to keep old devices at home","Informal workshops pay households more for old devices","Formal plants accept only laptops"],"answer":2,"explanation":"The passage states that formal plants struggle 'because the informal sector pays households more for their old devices'.","difficulty":"moderate","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-66","question":"Passage: People who hesitate to vaccinate their children are often portrayed as ignorant or selfish. Researchers who actually talk to them usually find something different: parents who love their children and are frightened of doing them harm. Many have read alarming stories online or heard of a neighbour's child who fell ill after an injection, even if the illness had nothing to do with it. Lecturing such parents, or mocking them, tends to make them dig in. What works better is patient conversation with someone they trust — often their own family doctor or a local health worker — who listens to their fears before answering them. Trust, once lost, is rebuilt slowly, one conversation at a time, and no advertising campaign can do the job on its own. Question: According to the passage, mocking hesitant parents usually:","options":["has no effect on their decisions","persuades them to vaccinate quickly","makes them hold on to their views more firmly","makes them trust their doctors more"],"answer":2,"explanation":"The passage says lecturing or mocking 'tends to make them dig in', i.e. hold their position more firmly.","difficulty":"moderate","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-67","question":"Passage: Thousands of pieces of debris now circle the Earth: dead satellites, spent rocket stages and fragments from collisions. Even a fleck of paint, travelling at several kilometres a second, can damage a working satellite. The real fear is a chain reaction. When two large objects collide, they shatter into thousands of fragments, each of which can strike another object and create more fragments. If this cascade ever ran out of control, some orbits could become too dangerous to use for generations, threatening the satellites that guide aircraft, forecast weather and carry phone signals. Space agencies now require new satellites to leave orbit within a set time after their missions end, and several companies are testing ways to capture old debris. Cleaning up space, however, is far harder than littering it. Question: The 'chain reaction' feared in the passage refers to:","options":["collisions producing fragments that cause further collisions","satellites falling back to Earth one after another","rockets exploding during launch","phone networks failing in succession"],"answer":0,"explanation":"The passage explains that colliding objects shatter into fragments which strike other objects and create more fragments — a cascade of collisions.","difficulty":"moderate","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-68","question":"Passage: In some countries, people are organ donors unless they choose otherwise; in others, they must actively sign up to become donors. The difference sounds minor, yet donor rates in 'opt-out' countries are often dramatically higher. Most people do not hold strong views either way, and they simply stay with whatever option is set as the default. Policymakers have taken note. Defaults are now used to raise pension savings, by enrolling employees automatically while letting them withdraw if they wish. Such 'nudges' are attractive because they preserve freedom of choice while steering behaviour. Critics worry, though, that a government skilled at nudging could just as easily steer people towards choices that serve the state rather than the citizen. The tool, in other words, is only as trustworthy as the hand that uses it. Question: The critics' concern about nudges is that:","options":["they have no effect on people's behaviour","they remove all freedom of choice from citizens","they are too expensive for governments to use","the same technique could be used to serve the government's own interests"],"answer":3,"explanation":"Critics fear a government 'could just as easily steer people towards choices that serve the state rather than the citizen'. The passage itself says nudges preserve freedom of choice.","difficulty":"moderate","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-69","question":"Passage: A few years ago, brightly coloured shared bicycles appeared on the streets of many cities, unlocked by a phone app and left anywhere after use. Investors poured in money, and companies flooded pavements with tens of thousands of bikes. Within months, many of the schemes collapsed. Bikes were vandalised, stolen or dumped in rivers; pavements were blocked by heaps of abandoned cycles; and companies, competing to grow fast, charged fares too low to cover repairs. The idea itself was not foolish — cities that later introduced smaller, well-managed schemes with docking stations and fair prices have seen steady use. The lesson is that a good idea, scaled up recklessly, can look like a bad one. Investors who judged the idea by the wreckage drew exactly the wrong conclusion. Question: The author would most likely agree that the early shared-bicycle schemes failed mainly because of:","options":["the basic idea of shared bicycles being unsound","reckless expansion and poor management","a lack of interest among city residents","government bans on bicycles"],"answer":1,"explanation":"The author says 'the idea itself was not foolish' and blames reckless scaling, rock-bottom fares and poor upkeep; well-managed schemes later succeeded.","difficulty":"moderate","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-70","question":"Passage: Wetlands were long regarded as wasteland — damp, mosquito-ridden places best drained and built upon. Scientists now describe them as the kidneys of the landscape. Reeds and microbes in marshes filter pollutants from water that passes through them; the spongy soil soaks up floodwater in the monsoon and releases it slowly in the dry months; and the shallow waters shelter fish and migratory birds. When a city fills in its wetlands for housing, it often discovers the loss only during the next heavy rain, when water that once spread harmlessly into the marsh floods streets and homes instead. Restoring a wetland is possible, but it costs far more than protecting one, and some of what is lost never fully returns. Question: In calling wetlands 'the kidneys of the landscape', scientists mainly emphasise their role in:","options":["breeding mosquitoes","producing food for cities","filtering and cleaning water","providing land for housing"],"answer":2,"explanation":"Kidneys filter blood; the analogy is explained by the next sentence about reeds and microbes filtering pollutants from water.","difficulty":"moderate","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-71","question":"Passage: Rooftop vegetable gardens have become fashionable in many cities. Enthusiasts claim they can make households self-sufficient in vegetables, cool buildings in summer and reduce the food miles of the city. The last two claims are reasonable. A layer of soil and plants does keep the room below cooler, and a tomato grown on one's roof travels no distance at all. The first claim, however, deserves scepticism. A typical rooftop can produce a useful supplement of greens and herbs, but feeding a family through the year would need far more space, sunlight and labour than most city roofs or residents can offer. The value of rooftop gardens may lie less in the quantity of food they produce than in reconnecting city people with how food is grown. Question: Which of the enthusiasts' claims does the author doubt?","options":["That rooftop gardens cool the rooms below them","That rooftop gardens can make households self-sufficient in vegetables","That rooftop gardens reduce food miles","That rooftop gardens reconnect people with food growing"],"answer":1,"explanation":"The author calls the cooling and food-miles claims reasonable but says 'The first claim, however, deserves scepticism' — self-sufficiency. Reconnection is the author's own suggestion, not the enthusiasts'.","difficulty":"hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-72","question":"Passage: Each time a doping scandal breaks, officials promise tougher testing. Yet testers are almost always a step behind, and athletes and their advisers know it well. New substances are designed to be invisible to existing tests, and by the time a test is developed, athletes have moved on to something else. For this reason, many anti-doping agencies now store athletes' samples for years so that they can be retested when better methods arrive. Several medals have been stripped long after the events, when old samples finally revealed what had been hidden. The threat of future detection may deter cheats more than today's tests do. An athlete can perhaps outwit the laboratory of the present; it is much harder to outwit the laboratory of the future. Question: The main point of the last two sentences is that:","options":["the possibility of later retesting may discourage doping more than current tests","present-day laboratories are completely ineffective","athletes should be tested only after they retire","stripping medals years later is unfair to athletes"],"answer":0,"explanation":"They argue that stored samples face 'the laboratory of the future', so the threat of future detection deters cheats. The author does not call present tests useless or later penalties unfair.","difficulty":"hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-73","question":"Passage: When the last speakers of a village's dialect die, their songs, recipes and memories of famines and festivals often die with them. Oral history projects try to prevent this by recording elderly people as they talk about their lives. The recordings are rarely dramatic. A grandmother describes how rice was husked by hand; a retired postman lists the villages on his old route. Yet historians value such accounts precisely because they are ordinary. Official records tell us what kings decreed and what taxes were collected; they seldom tell us how people actually lived. The danger is that these projects capture voices but not context — a recording without notes on who is speaking, and when, can puzzle future listeners as much as it helps them. Question: According to the passage, historians value oral accounts mainly because they:","options":["are easy to understand without any context","describe dramatic events in great detail","are more accurate than official records about taxes","record everyday life that official documents tend to ignore"],"answer":3,"explanation":"Historians value them 'precisely because they are ordinary' — official records seldom tell how people actually lived. The passage warns that recordings without context can puzzle listeners.","difficulty":"hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-74","question":"Passage: Fact-checking websites have multiplied, yet false stories continue to spread faster than corrections. One reason is timing: a fact-check usually appears hours or days after the false claim, by which time the claim has been shared thousands of times. Another is that corrections rarely reach the people who saw the original story. A third, more troubling reason is that some people share stories not because they believe them but because the stories express how they feel. For such readers, a fact-check misses the point, rather as a weather report misses the point of a poem about rain. Fighting misinformation may therefore require not only checking facts but also understanding why certain falsehoods feel true to those who share them. A correction that ignores this may be accurate and still useless. Question: The comparison with 'a weather report' and 'a poem about rain' suggests that:","options":["fact-checkers should write more poetically","weather reports are often inaccurate","poems spread faster than news stories","some false stories are shared for their emotional meaning, which a factual correction does not address"],"answer":3,"explanation":"Just as a weather report does not engage with what a poem expresses, a fact-check does not engage with the feelings that make people share a story.","difficulty":"hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-75","question":"Passage: Mr Dastur repaired clocks in a shop so narrow that customers had to stand sideways. He never advertised and kept no fixed hours, yet people brought him clocks from all over the city, some of them a hundred years old. He worked slowly, and when anyone complained, he would hold up a tiny brass wheel and say, 'This was made by a man who was not in a hurry. I will not insult him by being in one.' When he died, his nephew turned the shop into a mobile-phone store. It is busy and brightly lit, and the young man is courteous and quick. But on the shelf behind the counter, he has kept one of his uncle's clocks, which he winds every Sunday, though he cannot quite say why. Question: The nephew's habit of winding the clock every Sunday most likely suggests:","options":["a plan to reopen the clock shop","an unspoken respect for his uncle and the values he stood for","that the phone store has failed","dislike of his uncle's slow ways"],"answer":1,"explanation":"He keeps and winds the clock without being able to explain why, hinting at an inarticulate attachment to his uncle and his unhurried craft. Nothing suggests reopening the shop or failure of the store.","difficulty":"hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-76","question":"Passage: Sand seems limitless, yet it is one of the most heavily extracted materials on Earth. Concrete, glass and the land reclaimed for new ports all need it in huge quantities. Desert sand, ironically, is of little use for construction, because wind has rounded its grains so that they do not bind well. Builders want the angular sand found in riverbeds and coasts. As a result, rivers in many countries are being dredged faster than they can replenish themselves. Riverbeds sink, bridges are undermined, groundwater falls, and fish lose their breeding grounds. In some places, illegal mining is run by gangs who threaten officials and journalists. Few people think about sand at all, which is partly why its exploitation has gone so far unchecked. Question: Why, according to the passage, is desert sand of little use in construction?","options":["It contains too much salt","It is too expensive to transport from deserts","Its grains are rounded by wind and do not bind well","Governments have banned its use"],"answer":2,"explanation":"The passage explains that wind has rounded desert sand grains 'so that they do not bind well'; builders need angular river and coastal sand.","difficulty":"hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-77","question":"Passage: Electric buses are quieter and cleaner than diesel ones, and their running costs are lower. Their purchase price, however, is much higher, largely because of the batteries. Many city transport bodies, already in debt, cannot afford to buy them outright. A newer approach is to lease the buses: a private company buys and maintains them, and the city pays a fee for each kilometre run. The city avoids the large upfront cost, and the company carries the risk if the buses break down. Critics warn that long contracts could lock cities into paying high fees for decades. Supporters reply that without such arrangements, most cities would not be able to switch to electric buses at all. A costly bus on the road, they say, is better than a cheap plan on paper. Question: Which of the following is an assumption underlying the supporters' reply?","options":["Most cities cannot raise the money to buy electric buses outright","Private companies never charge high fees","Diesel buses will soon be banned","Electric buses have lower purchase prices than diesel buses"],"answer":0,"explanation":"Supporters claim that without leasing most cities could not switch at all, which assumes they cannot afford outright purchase. The passage says the purchase price is much higher, not lower.","difficulty":"hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-78","question":"Passage: Digital payments have spread rapidly, and many people now pay for tea, vegetables and bus tickets with their phones. Governments welcome the change, since digital transactions are easier to tax and trace than cash. But a fully cashless economy would leave some people behind: the elderly who are uncomfortable with smartphones, workers in areas with poor network coverage, and those who cannot afford a smartphone at all. There is also the question of resilience. When servers fail or networks go down during floods, digital payments stop, while cash continues to work. A sensible policy, then, would encourage digital payments without making cash disappear. The aim should be choice, not compulsion. A payment system, like a road, should serve everyone who needs to use it, not merely those who travel fastest. Question: The author's argument would be most WEAKENED if it were shown that:","options":["digital payments are easier to tax","many elderly people prefer cash","digital payment systems keep working reliably even when networks fail during disasters","some rural areas have poor network coverage"],"answer":2,"explanation":"One of the author's reasons for keeping cash is resilience — cash works when networks fail. Evidence that digital payments work reliably in such conditions would undercut that reason. The other options support or are neutral to the argument.","difficulty":"hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-79","question":"Passage: Child prodigies are celebrated on television and in newspapers: the eight-year-old who solves complex sums, the ten-year-old violinist who plays with an orchestra. Yet studies that follow such children into adulthood find that only a minority become eminent in their fields. Some lose interest; others burn out under the pressure of expectations; many simply turn into competent but ordinary adults. The skills that make a prodigy — mastering what is already known, quickly and precisely — are different from those that make an innovator, who must question what is known and risk failure. A child praised constantly for being brilliant may become afraid of the very mistakes from which originality grows. Praising effort rather than talent, some psychologists suggest, may protect children from this trap. Question: The passage suggests that constant praise for brilliance may harm a gifted child by:","options":["making the child afraid of making mistakes","reducing the child's speed in learning","causing the child to lose interest in praise","preventing the child from mastering known skills"],"answer":0,"explanation":"The last sentence says such a child 'may become afraid of the very mistakes from which originality grows'.","difficulty":"hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-80","question":"Passage: The fair came to our village every year after the harvest. For three days the dusty ground behind the temple became a city of tents: bangle sellers, sweet makers, a giant wheel that creaked alarmingly, and a man who swallowed swords for a fee. My father gave us each two rupees, a sum that seemed limitless until we reached the first stall. I remember spending mine on a tin whistle that broke the same evening, and feeling no regret at all. I went back to the village last year. The fair still happens, but it is smaller; the giant wheel is gone, and children walk around looking at their phones. I bought a tin whistle anyway. It broke the same evening, and this time, oddly, I minded. Question: Why does the narrator mind the broken whistle 'this time'?","options":["Because the whistle was much more expensive now","Because the whistle now stands for a past that he can no longer recapture","Because his children wanted the whistle","Because the seller refused to replace it"],"answer":1,"explanation":"As a child the joy lay in the moment; now the whistle carries nostalgia for a vanished fair and childhood, so its breaking hurts. Nothing is said about cost, his children or a refusal.","difficulty":"hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-81","question":"Passage: Seed banks store frozen samples of crop varieties so that they are not lost forever. The best known lies inside a mountain on a remote Arctic island, but hundreds of smaller banks exist around the world. Their value became clear when a war damaged a seed bank in the Middle East: scientists were able to restore its collection from duplicates stored abroad. Yet seed banks have a limitation. A seed frozen today is a snapshot of a plant adapted to today's conditions. In the field, farmers' varieties keep evolving as they adapt to new pests and a changing climate. Conservation in vaults and conservation on farms are therefore complementary; neither, on its own, is enough. A vault preserves the past; a farm keeps writing the future. Question: The author's main point about seed banks is that they:","options":["contain only seeds adapted to Arctic conditions","have made on-farm conservation unnecessary","are too vulnerable to war to be useful","are valuable but must be combined with farmers continuing to grow traditional varieties"],"answer":3,"explanation":"The author praises seed banks but notes that frozen seeds stop evolving, so vault and on-farm conservation are 'complementary; neither ... is enough'.","difficulty":"hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-82","question":"Passage: Lantana, a flowering shrub from the Americas, was brought to India as an ornamental hedge in the nineteenth century. Today it covers vast areas of forest, forming thickets so dense that native grasses and saplings cannot grow beneath them. Deer and other grazers lose their food, and the animals that prey on them follow. Clearing lantana is labour-intensive, and if the roots are not removed it simply grows back, often more vigorously. Some forest departments have turned the problem into an opportunity, training villagers to make furniture and baskets from lantana stems. The scheme provides income and removes the shrub at the same time. It is, however, a modest answer to an immense problem; the rate of clearing remains far below the rate of spread. Question: Which of the following best describes the author's assessment of the furniture-making scheme?","options":["It has completely eliminated lantana from forests","It is helpful but far too small to solve the problem","It has made lantana spread faster","It is a waste of the villagers' time"],"answer":1,"explanation":"The author calls it an opportunity that provides income and removes the shrub, but 'a modest answer to an immense problem' since clearing lags far behind spread.","difficulty":"hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-83","question":"Passage: Modern zoos describe themselves as centres of conservation rather than entertainment. Some have indeed helped save species: animals bred in captivity have been released to rebuild wild populations that had nearly vanished. Critics point out, however, that most animals in zoos belong to species that are not endangered at all, and that some animals — particularly large, wide-ranging ones such as elephants and polar bears — show signs of stress in even the best enclosures. Zoos reply that visitors who see living animals are more likely to support conservation. That may be true, but it is hard to prove. Perhaps the fairest conclusion is that zoos can be justified for some species and not for others. A blanket verdict either way says more about the speaker than about the animals. Question: The author's position on zoos is best described as:","options":["uninterested in the question","entirely favourable to zoos","entirely opposed to zoos","qualified — justified for some species but not for all"],"answer":3,"explanation":"The author concedes the zoos' successes and the critics' points, then concludes that 'zoos can be justified for some species and not for others' — a qualified view.","difficulty":"hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-84","question":"Passage: Office workers in many organisations spend a large part of their week in meetings, and surveys suggest that a good share of those meetings are considered unproductive by the people who attend them. The cost is not only the hours spent in the room. Deep, focused work requires long stretches of uninterrupted time, and a day broken by meetings at ten, twelve and three leaves only short gaps in which little serious thinking is possible. Some companies have introduced 'no-meeting days' or require every meeting to have a written agenda and a fixed end time. Employees report that such rules feel restrictive at first, but that they soon find themselves finishing more work in fewer hours. Some even say they enjoy the meetings that remain, because there are fewer of them. Question: According to the passage, a hidden cost of frequent meetings is that they:","options":["break the day into gaps too short for focused work","require expensive meeting rooms","make employees work longer hours in the room","prevent written agendas from being prepared"],"answer":0,"explanation":"Beyond the hours in the room, meetings fragment the day so that the gaps are too short for deep work — this is the cost the passage highlights.","difficulty":"hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-85","question":"Passage: Several countries have banned smartphones in school classrooms. Supporters argue that phones distract pupils, encourage cyberbullying and reduce the amount of face-to-face play during breaks. Early reports from some schools describe calmer classrooms and livelier playgrounds. Opponents counter that phones can be useful learning tools, that pupils need to learn self-control rather than have temptations removed, and that bans are hard to enforce. Both sides, however, often rely on anecdotes. Carefully designed studies comparing similar schools with and without bans are still few, and their results are mixed. Until more such evidence is available, the debate is likely to be settled by conviction rather than by data — which is perhaps not the best way to make decisions about children. Question: What is the author's main concern in the passage?","options":["That bans are always impossible to enforce","That smartphones are the main cause of cyberbullying","That the debate is driven more by belief than by solid evidence","That pupils should be allowed to use phones freely"],"answer":2,"explanation":"The author notes both sides rely on anecdotes and worries that the issue will be 'settled by conviction rather than by data'. He takes no side on the ban itself.","difficulty":"hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-86","question":"Passage: Many cities now require new buildings above a certain size to install rainwater harvesting systems. On paper the rule is admirable: rooftops collect water, which is filtered and channelled into tanks or into the ground to recharge aquifers. In practice, surveys in several cities have found that a large share of such systems do not work. Pipes are blocked by leaves, filters are never cleaned, and recharge pits fill with silt. The systems were installed to obtain a completion certificate, and nobody was responsible for them afterwards. The lesson extends beyond rainwater. Rules that demand a one-time installation, without anyone checking that the thing keeps working, tend to produce structures that exist mainly on paper. Inspection, not installation, is what turns a rule into a result. Question: The 'lesson' that 'extends beyond rainwater' is that:","options":["rules requiring one-time installation fail unless continued functioning is checked","rainwater harvesting is an expensive mistake","all building rules should be abolished","completion certificates should be issued faster"],"answer":0,"explanation":"The author generalises: rules demanding only installation, with no one checking that systems keep working, produce structures that 'exist mainly on paper'.","difficulty":"hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-87","question":"Passage: As summers grow hotter, the people most at risk are not those in air-conditioned offices but those who work outdoors — construction labourers, street vendors, farm workers and delivery riders. When the body cannot shed heat, it suffers exhaustion and, in severe cases, heatstroke, which can be fatal. Yet many of these workers are paid by the day or by the task, so resting in the afternoon means losing income. Some cities have started 'heat action plans', which shift working hours to cooler parts of the day, provide drinking water and shaded rest areas, and send warnings by phone when temperatures soar. Such plans cost little. Their success, however, depends on employers accepting that a worker's lost hour is cheaper than a worker's lost life. Question: Why, according to the passage, do many outdoor workers not rest during the hottest hours?","options":["Because they do not feel the heat","Because they are paid by the day or task and would lose income","Because employers provide air-conditioned rest areas","Because heat action plans forbid resting"],"answer":1,"explanation":"The passage says many are paid by the day or by the task, 'so resting in the afternoon means losing income'.","difficulty":"hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-88","question":"Passage: Urban planners rarely discuss public toilets, yet their absence shapes how half the population moves through a city. Men, however inconvenienced, can usually find somewhere to relieve themselves. Women often cannot, and many simply drink less water before leaving home or avoid long journeys altogether. Surveys in several Indian cities have found that the shortage of clean, safe and lit toilets is one reason women give for not taking up jobs far from home. A toilet may seem a trivial matter beside metro lines and flyovers. But a city that offers women fast trains and no toilets has offered them only half a journey. Planners who measure success by kilometres of track, and never ask who can actually use it, will keep missing this point. A few cities have begun to map toilets alongside bus stops, which is a modest but telling start. Question: The phrase 'only half a journey' implies that:","options":["metro lines cover only half of each city","women travel only half as far as men","transport alone is not enough if basic facilities that women need are missing","women prefer shorter train rides"],"answer":2,"explanation":"The author argues that without toilets, women may avoid long trips despite good transport; transport without such facilities serves them only partially.","difficulty":"hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-89","question":"Passage: Most startups fail, and most founders know this when they begin. Studies of failed startups suggest that running out of money is rarely the real cause; it is the final symptom. More often, the company built a product that not enough people wanted, or kept spending on growth before finding out whether customers would stay. Founders who have failed once are sometimes more successful the second time, not because failure itself teaches, but because they reflect on what went wrong. Others repeat the same mistakes. A culture that treats failure as shameful discourages such reflection; a culture that celebrates failure uncritically can be just as unhelpful. What matters is what one learns, not merely that one has failed. A failure examined honestly is an education; a failure merely survived is only an expense. Question: The author's view of 'celebrating failure' is that:","options":["it causes companies to run out of money","it is the main reason second startups succeed","it is always better than treating failure as shameful","it is unhelpful if it is uncritical, because the value lies in learning from failure"],"answer":3,"explanation":"The author says celebrating failure 'uncritically can be just as unhelpful' as shaming it; 'what matters is what one learns'.","difficulty":"hard","source":"IBPS PO · SBI PO · CDS pattern"},
  {"id":"eng-reading-comprehension-90","question":"Passage: Advertisements rarely lie outright; they do not need to. A shampoo is 'up to 70 per cent stronger' — stronger than what, and measured how? A biscuit contains 'goodness of wheat', a phrase that sounds healthy but promises nothing measurable. A juice is labelled 'no added sugar', which may be true even if it is naturally loaded with sugar. Such phrases work because readers fill in the gaps with what they want to believe. The advertiser has made no false claim, yet the buyer walks away with a false impression. Consumer protection laws are good at punishing lies; they are much weaker against carefully chosen words that mislead without lying. The careful reader's best defence is a simple question: compared with what, and measured how? Asked often enough, it empties many slogans of their magic. Question: According to the passage, why are consumer protection laws weak against such advertisements?","options":["Because the advertisements mislead without making any literally false claim","Because advertisers pay heavy fines willingly","Because such advertisements are rarely seen by buyers","Because the laws do not cover food products"],"answer":0,"explanation":"The passage says these phrases make 'no false claim' yet create a false impression; laws are 'good at punishing lies' but weaker against misleading wording.","difficulty":"hard","source":"IBPS PO · SBI PO · CDS pattern"}
];

export default questions;
